function showScreen(s){
  ["start","test","results","review"].forEach(function(id){
    document.getElementById("screen-"+id).style.display = id===s?"block":"none";
  });
  window.scrollTo(0,0);
  state.screen=s;
}

function goStart(){
  clearTimerInterval();
  showScreen("start");
}

